#include "lazyipdca_qcqp/solver.hpp"
#include "../src/newton_cost_ledger.hpp"
#include <sstream>
#include <iostream>
#include <stdexcept>
#include <cmath>
using namespace lazyipdca::qcqp;
void check(bool v,const char* s){if(!v)throw std::runtime_error(s);}
struct Buffer:std::stringbuf {int flushes=0;int sync() override {++flushes;return 0;}};
struct Capture {Buffer buffer;std::streambuf* old;Capture():old(std::cout.rdbuf(&buffer)){}~Capture(){std::cout.rdbuf(old);}};
Settings config(){Settings s;s.outer_algorithm="lazy-newton";s.ln_engine="atomic";s.linear_backend="native";s.verbose=false;return s;}
QuadraticFunction q(Vec linear,double c=0,double h=0){QuadraticFunction a;a.linear=linear;a.constant=c;a.hessian.n=linear.size();if(h)a.hessian.entries={{0,0,h}};return a;}
void accounting(const Result& r){const auto& s=r.lazy_newton;double total=0,core=0;for(int i=0;i<(int)NewtonCost::Count;++i){check(std::isfinite(s.cost_seconds[i])&&s.cost_seconds[i]>=0,"invalid time sector");total+=s.cost_seconds[i];if(i>=(int)NewtonCost::Evaluation&&i<=(int)NewtonCost::CoreOther)core+=s.cost_seconds[i];}check(std::abs(total-s.solver_wall_seconds)<1e-10,"exclusive sectors do not sum to wall");check(std::abs(core-s.core_solve_seconds)<1e-12,"core sectors do not sum");check(s.solver_wall_seconds>=r.elapsed_seconds,"wall excludes cleanup boundary");}
std::vector<int> rows(const std::string& text){std::vector<int> r;std::istringstream lines(text);std::string line;while(std::getline(lines,line)){std::istringstream in(line);int k;double objective;if(in>>k>>objective)r.push_back(k);}return r;}
void levels(){QCQPProblem p;p.n=1;p.x0={-2};p.lb={-5};p.ub={5};p.objective=q({-3},4.5,1);p.inequalities={q({1},-1)};auto s=config();Result base;{Capture c;base=Solver(s).solve(p);check(c.buffer.str().empty(),"level zero emitted output");}check(base.status==Status::Solved&&base.lazy_newton.working_set_retries>0,"activation fixture missing retries");accounting(base);
for(int level=1;level<=4;++level){s.live_display_level=level;Capture c;auto r=Solver(s).solve(p);const auto text=c.buffer.str();accounting(r);check(r.x==base.x&&r.certificate_inequality_multipliers==base.certificate_inequality_multipliers&&r.certificate_lower_multipliers==base.certificate_lower_multipliers&&r.certificate_upper_multipliers==base.certificate_upper_multipliers,"display changed endpoint");check(r.outer_iterations==base.outer_iterations,"display changed iterations");check(c.buffer.flushes>1,"live rows not flushed");for(int f=0;f<4;++f){const auto& a=r.lazy_newton.calls[1][f];const auto& b=base.lazy_newton.calls[1][f];check(a.values==b.values&&a.gradients==b.gradients&&a.jacobian_products==b.jacobian_products&&a.hessian_assemblies==b.hessian_assemblies,"diagnostics polluted core counters");}
if(level<4){auto ids=rows(text);check((int)ids.size()==r.outer_iterations+1,"outer rows duplicated or missing");for(int i=0;i<(int)ids.size();++i)check(ids[i]==i,"outer iteration not sequential");check(text.find("[KKT]")==std::string::npos&&text.find("WS+")==std::string::npos,"internal attempt leaked");}
check(text.find("      work")==std::string::npos&&text.find("      atoms objective=")==std::string::npos,"subrows remain in column display");check((text.find("traceR")!=std::string::npos)==(level>=3),"atom columns level mismatch");if(level==1)check(r.lazy_newton.iteration_history.empty(),"minimal display retained detailed history");if(level==4)check(text.find("[CURV]")!=std::string::npos,"full curvature missing");}
s.live_display_level=1;s.max_outer_iterations=2;s.live_iteration_every=100;{Capture c;auto r=Solver(s).solve(p);accounting(r);auto ids=rows(c.buffer.str());check(ids==std::vector<int>({0,2}),"stride did not force unique terminal state");}
s=config();s.live_display_level=0;s.live_curvature=true;s.live_iterations=true;{Capture c;Solver(s).solve(p);check(c.buffer.str().empty(),"explicit zero did not override aliases");}}
void call_counts(){QCQPProblem p;p.n=2;p.x0={0,0};p.lb={-INFINITY,-INFINITY};p.ub={INFINITY,INFINITY};p.objective=q({0,0},0,2);p.equalities={q({0,1})};p.inequalities={q({0,0},-2)};auto s=config();for(bool sparse:{true,false}){s.lazy_newton_sparse_certificate=sparse;auto r=Solver(s).solve(p);check(r.status==Status::Solved&&r.outer_iterations==0,"stationary fixture took steps");accounting(r);for(int f=0;f<3;++f){const auto& prep=r.lazy_newton.calls[0][f];const auto& core=r.lazy_newton.calls[1][f];const auto& cert=r.lazy_newton.calls[3][f];check(prep.values==3&&prep.gradients==3,"initial function count incorrect");check(core.values==1&&core.gradients==1,"stationary core function count incorrect");check(core.hessian_assemblies==0&&core.hessian_products==0,"stationary point assembled Hessian");check(cert.gradients==1&&cert.values==(sparse||f==0?1:2),"original certificate count incorrect");}check(r.lazy_newton.calls[1][3].values==0,"absent bound rows counted");}
p.lb=p.ub=p.x0;auto fixed=Solver(s).solve(p);check(fixed.status==Status::Solved,"fixed fixture failed");accounting(fixed);check(fixed.lazy_newton.calls[1][0].values==0,"fixed variables took core evaluations");}
void ledger_nesting(){LazyNewtonStatistics stats;detail::NewtonCostLedger c(stats,std::chrono::steady_clock::now());{detail::NewtonCostLedger::Scope prep(c,NewtonCost::Preparation);{detail::NewtonCostLedger::Scope eval(c,NewtonCost::Evaluation);check(c.phase()==0,"nested evaluation lost setup phase");}}{detail::NewtonCostLedger::Scope diag(c,NewtonCost::Diagnostics);{detail::NewtonCostLedger::Scope factor(c,NewtonCost::Factorization);check(c.phase()==2,"nested diagnostic became core");}}check(c.phase()==1,"ledger failed to restore core");c.finish();double wall=stats.solver_wall_seconds;c.finish();check(wall==stats.solver_wall_seconds,"finish was not idempotent");}
int main(){try{levels();call_counts();ledger_nesting();std::cout<<"PASS progressive flushed outer display, exact accounting, scalar evaluation counts and primal-dual parity\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<"\n";return 1;}}
